Translate("ptBR", "thunder-bluff", {
	title = "Penhasco do Trovão",
	aliases = { "a cidade do Penhasco do Trovão" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Penhasco do Trovão é a capital dos {link:tauren}tauren{/link}, erguida sobre um grupo de platôs varridos pelo vento que se elevam centenas de pés acima das planícies de {link:mulgore}Mulgore{/link}. Pontes de madeira e corda balançam entre as alturas, e cada platô é coroado de tendas, casas compridas, totens pintados e cabanas espirituais. Grandes elevadores de corda e madeira levam os viajantes desde o capim lá embaixo, e cavaleiros de mantícora circulam a torre central. É uma cidade de muitas tribos e um refúgio para caçadores, mercadores e artesãos de todo tipo. De sua cabana no platô central, o Grande Chefe {link:cairne-bloodhoof}Cairne Bloodhoof{/link} vela por todos eles.]=],
		},
		{
			title = "Origens",
			text = [=[Por incontáveis gerações os {link:tauren}tauren{/link} não tiveram cidade. Eram nômades, e os {link:centaurs}centauros{/link} os caçaram pelas planícies até que suas tribos ficassem poucas e dispersas. {link:cairne-bloodhoof}Cairne{/link}, dos Bloodhoof, sonhava com uma terra onde seu povo pudesse viver em paz. Com a ajuda de {link:thrall}Thrall{/link} e dos orcs da {link:horde}Horda{/link}, os tauren expulsaram os centauros de {link:mulgore}Mulgore{/link}. Nos platôs de seu extremo norte, Cairne construiu um refúgio onde os tauren de todas as tribos seriam bem-vindos. Nenhuma crônica registra o ano em que foi concluído. Com o tempo, as tribos dispersas vieram até ele e se uniram sob seu governo.]=],
		},
		{
			title = "Os Dias Atuais",
			text = [=[{link:cairne-bloodhoof}Cairne{/link} está velho, mas sua força e sabedoria ainda mantêm as tribos unidas. Nem toda tribo concorda com o caminho que ele escolheu. No {link:elder-rise}Platô dos Anciãos{/link}, {link:magatha-grimtotem}Magatha Grimtotem{/link}, a Velha Anciã dos Temível Totem, guarda seus próprios segredos e seus próprios guardas, e acredita que ela, e não Cairne, deveria liderar os {link:tauren}tauren{/link}. Ao lado dela, os druidas do {link:cenarion-circle}Círculo Cenariano{/link} cuidam de suas cabanas sob o {link:hamuul-runetotem}Arquidruida Hamuul Runetotem{/link}. Emissários dos {link:forsaken}Renegados{/link} vivem nos {link:the-pools-of-vision}Poços das Visões{/link} e ensinam no {link:spirit-rise}Platô dos Espíritos{/link}, sinal do pacto que os trouxe para a {link:horde}Horda{/link}. Os sábios da cidade são conhecidos em toda a Horda como historiadores. Nestes dias chegaram também rostos novos: sacerdotes de An'she, o sol, e elfos {link:skyborne}Skyborne{/link} que passam a caminho do acampamento da {link:earthen-ring}Harmonia Telúrica{/link} para {link:orgrimmar}Orgrimmar{/link}.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}Os {link:tauren}tauren{/link} de muitas tribos.{/b} Os Bloodhoof, os Runetotem, os Wildmane, os Thunderhorn, os Ragetotem, os Stonehoof, os Mistrunner e muitos outros exercem seus ofícios nos platôs.
• {b}Os Temível Totem.{/b} {link:magatha-grimtotem}Magatha{/link} e seus servos ocupam um canto do {link:elder-rise}Platô dos Anciãos{/link}.
• {b}Os druidas.{/b} Tauren do {link:cenarion-circle}Círculo Cenariano{/link}, liderados por {link:hamuul-runetotem}Hamuul Runetotem{/link}.
• {b}Os {link:forsaken}Renegados{/link}.{/b} Boticários, sacerdotes e magos enviados da {link:undercity}Cidade Baixa{/link}.
• {b}Viajantes da {link:horde}Horda{/link}.{/b} {link:orcs}Orcs{/link}, trolls e agora {link:skyborne}Skyborne{/link} vêm e vão por mantícora e elevador.]=],
		},
		{
			title = "História",
			text = [=[• {b}A Longa Marcha.{/b} Os orcs de {link:thrall}Thrall{/link} escoltaram o povo de {link:cairne-bloodhoof}Cairne{/link} pelos {link:the-barrens}Sertões{/link} até {link:mulgore}Mulgore{/link}, e Cairne comprometeu os {link:tauren}tauren{/link} com a {link:horde}Horda{/link}.
• {b}A {link:third-war}Terceira Guerra{/link}.{/b} Guerreiros tauren lutaram ao lado dos orcs, dos humanos e dos elfos noturnos na {link:battle-of-mount-hyjal}Batalha do Monte Hyjal{/link}.
• {b}A Fundação.{/b} Com os centauros expulsos, Cairne ergueu o Penhasco do Trovão e chamou as tribos para ele.
• {b}O Pacto com os {link:forsaken}Renegados{/link}.{/b} Quando os Renegados buscaram um lugar na Horda, os anciãos da {link:earthen-ring}Harmonia Telúrica{/link} insistiram que fossem ajudados. Cairne concordou, e os Renegados vieram ao Penhasco do Trovão como aliados.]=],
		},
		{
			title = "O Saber dos Penhascos",
			text = [=[• Os {link:tauren}tauren{/link} mantêm o costume de espalhar incenso aos ventos do penhasco sul do {link:hunter-rise}Platô dos Caçadores{/link}.
• Um jovem tauren que se apresenta diante do Grande Chefe usa um cocar, e os mais belos são feitos com penas de {link:harpies}harpia{/link} do norte.
• Os sábios do Penhasco do Trovão estudaram discos de metal trazidos de {link:uldaman}Uldaman{/link}, cujos glifos falam de um lugar perdido chamado {link:valley-of-the-watchers}Uldum{/link}.]=],
		},
	},
})

Translate("ptBR", "elder-rise", {
	title = "Platô dos Anciãos",
	sections = {
		{
			title = "Resumo",
			text = [=[O Platô dos Anciãos é o penhasco nordeste do {link:thunder-bluff}Penhasco do Trovão{/link}, o lar dos sábios da cidade. Os druidas do {link:cenarion-circle}Círculo Cenariano{/link} mantêm suas cabanas aqui sob o {link:hamuul-runetotem}Arquidruida Hamuul Runetotem{/link}, com sua filha Bashana, a jovem druida {link:nara-wildmane}Nara Wildmane{/link} e os mestres das artes druídicas ao lado deles. Numa cabana própria, guardada por dois guerreiros de seu clã, vive {link:magatha-grimtotem}Magatha Grimtotem{/link}, a Velha Anciã. Os dois anciãos dividem o mesmo platô e raramente a mesma opinião. Quem busca conselho sobre os males da terra, sejam de espíritos, de sonhos ou da própria terra, é enviado para cá.]=],
		},
	},
})

Translate("ptBR", "spirit-rise", {
	title = "Platô dos Espíritos",
	sections = {
		{
			title = "Resumo",
			text = [=[O Platô dos Espíritos é o penhasco oeste do {link:thunder-bluff}Penhasco do Trovão{/link}, onde os xamãs da família Skychaser ensinam os jovens a falar com os espíritos dos {link:elements}elementos{/link}. É também o platô dos estrangeiros. Sacerdotes e magos dos {link:forsaken}Renegados{/link} passaram a ensinar aqui, e uma trilha escondida desce do platô até a caverna dos {link:the-pools-of-vision}Poços das Visões{/link}, onde os boticários da {link:undercity}Cidade Baixa{/link} fazem seu trabalho. Nestes dias, um instrutor de paladinos também chegou ao platô. Para muitos {link:tauren}tauren{/link}, o Platô dos Espíritos é onde encontram pela primeira vez os mortos que agora são seus aliados.]=],
		},
	},
})

Translate("ptBR", "hunter-rise", {
	title = "Platô dos Caçadores",
	aliases = { "Platô do Caçador" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Platô dos Caçadores é o penhasco sul do {link:thunder-bluff}Penhasco do Trovão{/link}, o platô dos que vivem da caça e da lança. Os caçadores da família Thunderhorn treinam os jovens para rastrear e domar, e os guerreiros dos Ragetotem os ensinam a lutar. O grande caçador {link:melor-stonehoof}Melor Stonehoof{/link} lança daqui suas caçadas mais duras, contra feras que vivem fora da bênção da Mãe Terra. Do penhasco sul do platô, os {link:tauren}tauren{/link} espalham incenso aos ventos, como pede sua tradição, e contemplam toda {link:mulgore}Mulgore{/link}.]=],
		},
	},
})

Translate("ptBR", "the-pools-of-vision", {
	title = "Poços das Visões",
	aliases = { "os Poços das Visões" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Poços das Visões ficam numa caverna sob o {link:spirit-rise}Platô dos Espíritos{/link}, alcançada por uma trilha escondida. Água parada enche a caverna, e os {link:tauren}tauren{/link} a consideram sagrada. Nestes dias os poços se tornaram o lar dos emissários {link:forsaken}Renegados{/link} no {link:thunder-bluff}Penhasco do Trovão{/link}. A {link:apothecary-zamah}Boticária Zamah{/link}, da {link:royal-apothecary-society}Real Sociedade de Boticários{/link}, trabalha aqui, recebendo remessas estranhas e enviando outras. Foi a ela que {link:magatha-grimtotem}Magatha Grimtotem{/link} recorreu quando buscou uma cura para a doença da {link:stonetalon-mountains}Cordilheira das Torres de Pedra{/link}, e a cura que os Renegados ofereceram foi um veneno.]=],
		},
	},
})

Translate("ptBR", "cairne-bloodhoof", {
	title = "Cairne Bloodhoof",
	subtitle = "Grande Chefe dos Tauren",
	found = "Sua cabana no platô central do Penhasco do Trovão",
	hint = [=[Suba ao platô mais alto do Penhasco do Trovão e peça uma audiência com o Grande Chefe.]=],
	allegiance = "Tauren · Tribo Bloodhoof · Horda",
	aliases = { "Cairne", "Grande Chefe Cairne Bloodhoof" },
	sections = {
		{
			title = "Resumo",
			text = [=[Cairne Bloodhoof é o Grande Chefe dos {link:tauren}tauren{/link} e o fundador do {link:thunder-bluff}Penhasco do Trovão{/link}. Foi outrora chefe de uma única tribo, os Bloodhoof, que vagavam pelas planícies perto do Grande Mar e viviam com medo dos centauros. Hoje é o senhor de todas as tribos tauren e um dos grandes pilares da {link:horde}Horda{/link}. A idade o tornou mais lento, mas não o curvou. É um guerreiro sem igual, um juiz paciente e um amigo dos que honram a terra.]=],
		},
		{
			title = "Importância",
			text = [=[Cairne deu um lar a seu povo. Foi sua aliança com {link:thrall}Thrall{/link} que salvou os {link:tauren}tauren{/link} dos centauros, e sua palavra que os ligou à {link:horde}Horda{/link}. Por meio dele a Horda ganhou mais que guerreiros: ganhou um povo de profunda sabedoria e fé antiga. Nestes dias o Grande Chefe ainda mantém as tribos unidas, embora nem todas concordem com o rumo que ele toma.]=],
		},
		{
			title = "Feitos",
			text = [=[• Encontrou {link:thrall}Thrall{/link} nas planícies de {link:kalimdor}Kalimdor{/link} e lhe mostrou o caminho até o Oráculo do {link:stonetalon-peak}Morro das Torres de Pedra{/link}.
• Conduziu seu povo pelos {link:the-barrens}Sertões{/link} até {link:mulgore}Mulgore{/link} sob a proteção dos orcs.
• Comprometeu os {link:tauren}tauren{/link} com a {link:horde}Horda{/link} e lutou na {link:battle-of-mount-hyjal}Batalha do Monte Hyjal{/link}.
• Fundou o {link:thunder-bluff}Penhasco do Trovão{/link} e fez de Mulgore um lar para todas as tribos.
• Acolheu os {link:forsaken}Renegados{/link} na Horda.
• Mantém seus próprios batedores, os Longwalkers, e lhes confia seus segredos.]=],
		},
		{
			title = "Sem Registro",
			text = [=[As crônicas desta era pouco dizem da juventude de Cairne, ou dos anos antes de os centauros levarem sua tribo à beira da ruína.]=],
		},
	},
	chapters = {
		{
			title = "A Longa Marcha",
			hint = [=[Complete os Ritos da Mãe Terra e apresente-se diante do Grande Chefe.]=],
			text = [=[Antes que os {link:tauren}tauren{/link} tivessem um lar, os centauros caçavam o povo de Cairne de um acampamento a outro. Quando o jovem chefe guerreiro {link:thrall}Thrall{/link} os encontrou em batalha, Cairne viu nos orcs um povo tão selvagem quanto nobre. Falou a Thrall do Oráculo no norte. Thrall, por sua vez, jurou proteger as caravanas tauren através dos {link:the-barrens}Sertões{/link}, e os orcs rechaçaram onda após onda de centauros até que os tauren chegassem a {link:mulgore}Mulgore{/link}. Cairne não esqueceu a dívida. Seguiu Thrall até as {link:stonetalon-mountains}Torres de Pedra{/link} e, daquele dia em diante, os tauren marcharam com a {link:horde}Horda{/link}.]=],
		},
		{
			title = "O Chifre de Arra'chea",
			hint = [=[Prove seu valor ao Grande Chefe com uma caçada nas planícies abaixo.]=],
			text = [=[Para Cairne, um lugar no {link:thunder-bluff}Penhasco do Trovão{/link} não se conquista uma vez só. É preciso mantê-lo. Ele lembra a cada jovem {link:tauren}tauren{/link} que chega à sua cabana que seu povo é de caçadores, e o manda às planícies para rastrear e abater o grande kodo Arra'chea. Quando o chifre é trazido, ele envia um grupo para recolher o couro e a carne, para que nada da fera seja desperdiçado.]=],
		},
		{
			title = "Os Longwalkers",
			hint = "Traga ao Grande Chefe notícias de seu batedor desaparecido.",
			text = [=[Cairne enviou o Longwalker {link:perith-stormhoof}Perith Stormhoof{/link} para falar com os {link:palemane-gnolls}gnolls Jubalba{/link}, e os gnolls o fizeram prisioneiro. Quando chegou a notícia de que Perith estava a salvo, Cairne ficou aliviado. Chamou Perith de seu batedor de maior confiança e sua missão de extrema importância, e nada mais disse sobre que missão era essa.]=],
		},
		{
			title = "O Retorno dos Galath",
			hint = [=[Expulse os centauros de Mulgore e apresente-se ao Grande Chefe.]=],
			text = [=[A notícia de que os Galath haviam ousado atacar {link:mulgore}Mulgore{/link} despertou a ira do velho guerreiro. Ele expulsara os centauros destas planícies ao lado de {link:thrall}Thrall{/link}, e honrou os que os expulsaram de novo, para que os centauros se lembrassem da dor que os espera se voltarem.]=],
		},
	},
	mentions = {
		{ text = "Viagem ao {link:thunder-bluff}Penhasco do Trovão{/link}" },
		{
			text = [=[Explorando a {link:horde}Horda{/link}, uma hóspede {link:skyborne}Skyborne{/link} em sua cabana]=],
		},
		{
			text = [=[{link:rites-of-the-earthmother}Ritos da Mãe Terra{/link}, o último dos ritos]=],
		},
	},
	bonds = {
		{ id = "baine-bloodhoof", name = "Baine Bloodhoof", note = "seu filho" },
		{ id = "thrall", name = "Thrall", note = "seu amigo e chefe guerreiro" },
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "um amigo desde a infância" },
		{ id = "magatha-grimtotem", name = "Magatha Grimtotem", note = "sua rival entre os anciãos" },
		{ id = "perith-stormhoof", name = "Perith Stormhoof", note = "seu batedor de maior confiança" },
		{ id = "muln-earthfury", name = "Muln Earthfury", note = "ancião da Harmonia Telúrica" },
	},
})

Translate("ptBR", "magatha-grimtotem", {
	title = "Magatha Grimtotem",
	subtitle = "Velha Anciã dos Temível Totem",
	found = "Sua cabana no Platô dos Anciãos",
	hint = [=[Busque o conselho da Velha Anciã que vive no Platô dos Anciãos.]=],
	allegiance = "Clã Temível Totem · Penhasco do Trovão",
	aliases = { "Magatha", "a Velha Anciã" },
	sections = {
		{
			title = "Resumo",
			text = [=[Magatha Grimtotem é a Velha Anciã dos Temível Totem, uma xamã que muitos consideram a mais poderosa dos {link:tauren}tauren{/link}, e uma das mais velhas de seus anciãos. Vive numa cabana no {link:elder-rise}Platô dos Anciãos{/link}, servida por dois guerreiros de seu clã e por seu servo Rahauro. Muitos vêm a ela em busca de conselho, e ela o dá de bom grado. O que ela quer em troca, poucos sabem dizer.]=],
		},
		{
			title = "Importância",
			text = [=[Magatha é a grande rival de {link:cairne-bloodhoof}Cairne Bloodhoof{/link}. Buscou poder e prestígio quase a vida toda, e acredita que só ela está apta a liderar os {link:tauren}tauren{/link}. Os guerreiros de seu clã a seguem, e sonham em expulsar as raças inferiores de {link:kalimdor}Kalimdor{/link}. Ainda assim ela vive na cidade do Grande Chefe, senta-se entre seus anciãos e fala pelos {link:forsaken}Renegados{/link}, a quem ajudou mais que qualquer outro tauren.]=],
		},
		{
			title = "Feitos",
			text = [=[• Recebeu os dons de xamã ainda menina.
• Tornou-se matriarca dos Temível Totem por um casamento arranjado. Muitos suspeitam que ela mesma o arranjou. Seu companheiro morreu pouco depois num acidente de escalada que ninguém previu.
• Defendeu os {link:forsaken}Renegados{/link} quando seu pacto com a {link:horde}Horda{/link} foi proposto pela primeira vez.
• Busca um caminho, diz ela, para que os Renegados encontrem a trilha de volta à vida.
• Enviou emissários para negociar com os troggs das {link:ragefire-chasm}Cavernas Ígneas{/link}, sob {link:orgrimmar}Orgrimmar{/link}.]=],
		},
	},
	chapters = {
		{
			title = "A Doença sobre a Terra",
			hint = [=[Leve à Velha Anciã a aflição da Cordilheira das Torres de Pedra.]=],
			text = [=[Quando lhe chegou notícia dos espíritos perturbados da {link:stonetalon-mountains}Cordilheira das Torres de Pedra{/link}, Magatha disse que a terra não poderia ser curada enquanto a doença sobre ela não fosse removida. A doença era a {link:venture-company}Empreendimentos S.A.{/link}. Ela recorreu aos {link:forsaken}Renegados{/link}, dizendo que seu conhecimento das doenças fortaleceria a confiança entre os dois povos. Os boticários responderam com uma toxina, feita para se espalhar entre os goblins como uma praga.]=],
		},
		{
			title = "A Tábua de Beth'Amara",
			hint = "Leve uma tábua antiga à Velha Anciã.",
			text = [=[Da distante {link:azshara}Azshara{/link} veio uma tábua, enviada por uma agente chamada {link:jediga}Jediga{/link}, que recebera ordens de entregá-la nas mãos de Magatha. Magatha afirmou que ela talvez lhe mostrasse como os {link:tauren}tauren{/link} poderiam ajudar os {link:forsaken}Renegados{/link} a se tornar humanos de novo. Ficou satisfeita com o trabalho, e prometeu a Jediga seu pagamento.]=],
		},
		{
			title = "A Serpente da Vingança",
			hint = "Responda ao aviso da Velha Anciã sobre Arikara.",
			text = [=[Magatha encantou um pó que invocaria {link:arikara}Arikara{/link}, uma serpente da vingança, do fogo sagrado do {link:darkcloud-pinnacle}Pináculo da Nuvem Negra{/link}, em {link:thousand-needles}Mil Agulhas{/link}. Avisou que a serpente talvez estivesse perseguindo {link:cairne-bloodhoof}Cairne Bloodhoof{/link}, enfurecida porque muito do saber {link:tauren}tauren{/link} havia mudado. Os tauren da {link:freewind-post}Aldeia Vento Livre{/link} não conseguiam entender por que Arikara caçaria o Grande Chefe. Não duvidaram de Magatha. Ela era, diziam, sua xamã mais poderosa.]=],
		},
		{
			title = "Os Troggs das Cavernas Ígneas",
			hint = "Recupere a bolsa do emissário perdido de Magatha.",
			text = [=[Magatha buscou a paz com os troggs que haviam subido das profundezas sob {link:orgrimmar}Orgrimmar{/link}. Em vez disso, eles mataram seus diplomatas. Um de seus servos, {link:maur-raincaller}Maur{/link} Grimtotem, morreu nas {link:ragefire-chasm}Cavernas Ígneas{/link} agarrado a uma bolsa. Magatha a queria de volta, e declarou os troggs uma ameaça a toda a {link:horde}Horda{/link}.]=],
		},
	},
	mentions = {
		{ text = "A Velha Anciã" },
		{ text = "O Pagamento de Magatha a {link:jediga}Jediga{/link}" },
		{ text = "Fogo Sagrado" },
		{ text = "Testando a Força do Inimigo, enviada por seu servo Rahauro" },
		{ text = "Em Busca da Bolsa Perdida" },
	},
	bonds = {
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "seu rival" },
		{ id = "apothecary-zamah", name = "Boticária Zamah", note = "a renegada em quem ela confia" },
		{ id = "sage-truthseeker", name = "Sábio Truthseeker", note = "desconfia do pacto que ela defendeu" },
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "divide o Platô dos Anciãos" },
	},
})

Translate("ptBR", "hamuul-runetotem", {
	title = "Hamuul Runetotem",
	subtitle = "Arquidruida do Penhasco do Trovão",
	found = "Sua cabana no Platô dos Anciãos",
	hint = [=[Procure o velho druida que mantém sua cabana no Platô dos Anciãos.]=],
	allegiance = "Círculo Cenariano · Tauren",
	aliases = { "Arquidruida Hamuul Runetotem", "Hamuul", "Arquidruida Runetotem" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Arquidruida Hamuul Runetotem é o primeiro druida {link:tauren}tauren{/link} em muitas gerações e o líder dos druidas do {link:thunder-bluff}Penhasco do Trovão{/link}. Foi tocado pelos druidas que lutaram no {link:mount-hyjal}Monte Hyjal{/link} e, depois da guerra, procurou {link:malfurion-stormrage}Malfurion Stormrage{/link} e pediu para ser ensinado. É membro do {link:cenarion-circle}Círculo Cenariano{/link} e amigo de {link:cairne-bloodhoof}Cairne{/link} desde a infância.]=],
		},
		{
			title = "Importância",
			text = [=[Hamuul abriu aos {link:tauren}tauren{/link} os antigos caminhos dos elfos noturnos. Graças a ele, druidas dos dois povos agora trabalham lado a lado, e sua cabana no {link:elder-rise}Platô dos Anciãos{/link} é aonde os tauren recorrem quando a própria terra adoece.]=],
		},
		{
			title = "Feitos",
			text = [=[• Envia os jovens para ajudar os druidas que buscam um estranho poder que se infiltra nos {link:the-barrens}Sertões{/link}.
• Entrou no sonho para descobrir o que envenena os Sertões.
• Aconselha os jovens druidas a olhar além das brigas entre os povos em seus tratos com o Círculo.
• Estuda o solo de {link:un-goro-crater}Un'Goro{/link} e o crescimento do grão-da-manhã.]=],
		},
	},
	chapters = {
		{
			title = "Os Druidas da Presa",
			hint = "Leve ao Arquidruida as carapaças corrompidas dos Sertões.",
			text = [=[A corrupção nos oásis dos {link:the-barrens}Sertões{/link} levou à {link:wailing-caverns}Caverna Ululante{/link}. Hamuul entrou na terra dos sonhos e viu ali um culto de druidas, outrora nobres, que haviam perdido o rumo e agora serviam à corrupção. Ele era velho, e não podia ficar muito tempo no sonho. A jovem {link:nara-wildmane}Nara Wildmane{/link} ficou quando ele fugiu.]=],
		},
		{
			title = "Um Fragmento de Pesadelo",
			hint = "Entregue um fragmento estranho ao Arquidruida.",
			text = [=[Um fragmento do {link:emerald-dream}Sonho Esmeralda{/link} chegou a ele vindo de um druida que não queria falar a respeito. Hamuul olhou dentro dele, calou-se e disse apenas que as coisas no Sonho não eram como os druidas pensavam. Aconselhou que não era sábio falar de tais assuntos.]=],
		},
		{
			title = "Os Poços Purificados",
			hint = [=[Leve ao Penhasco do Trovão a notícia dos poços purificados de Mulgore.]=],
			text = [=[Quando {link:mull-thunderhorn}Mull Thunderhorn{/link} relatou que os três {link:water-wells-of-mulgore}poços de Mulgore{/link} haviam sido purificados, Hamuul disse que a alegria corria de novo pelos riachos, pois os poços servem tanto às feras quanto ao povo.]=],
		},
	},
	mentions = {
		{ text = "Os Oásis dos {link:the-barrens}Sertões{/link}" },
		{ text = "{link:nara-wildmane}Nara Wildmane{/link}" },
		{ text = "{link:rabine-saturna}Rabine Saturna{/link}" },
		{ text = "Solo de {link:un-goro-crater}Un'Goro{/link}" },
		{ text = "Pesquisa do Grão-da-manhã" },
	},
	bonds = {
