		{ id = "nara-wildmane", name = "Nara Wildmane", note = "uma jovem druida de espírito feroz" },
		{ id = "mull-thunderhorn", name = "Mull Thunderhorn", note = "mandou-lhe notícia dos poços" },
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "seu mestre" },
	},
})

Translate("ptBR", "sage-truthseeker", {
	title = "Sábio Truthseeker",
	subtitle = "Sábio do Penhasco do Trovão",
	found = "O platô inferior do Penhasco do Trovão",
	hint = [=[Procure o sábio que reúne o saber perdido de Azeroth para os tauren.]=],
	allegiance = "Penhasco do Trovão · Os Sábios",
	aliases = { "Truthseeker" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Sábio Truthseeker é um dos sábios do {link:thunder-bluff}Penhasco do Trovão{/link}, os historiadores dos {link:tauren}tauren{/link}. Reúne livros antigos, relíquias e segredos de todo o mundo e os estuda para seu povo. Confiaria a {link:cairne-bloodhoof}Cairne{/link} a própria vida. Não confia nos {link:forsaken}Renegados{/link}.]=],
		},
		{
			title = "Importância",
			text = [=[O Sábio fala pelos {link:tauren}tauren{/link} que duvidam do pacto com os mortos. Acredita que a {link:earthen-ring}Harmonia Telúrica{/link} teve boas intenções quando instou a {link:horde}Horda{/link} a ajudá-los, mas se pergunta quem sussurrava aos ouvidos de seu Conselho dos Anciãos. Ele também está à beira de um mistério mais profundo, que remonta aos criadores do mundo.]=],
		},
		{
			title = "Feitos",
			text = [=[• Buscou o Compêndio dos Caídos junto aos fanáticos do {link:scarlet-monastery}Monastério Escarlate{/link}.
• Estuda os discos de Norgannon trazidos de {link:uldaman}Uldaman{/link}.
• Ele e {link:nara-wildmane}Nara Wildmane{/link} seguem os discos rumo a {link:valley-of-the-watchers}Uldum{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Compêndio dos Caídos",
			hint = "Traga ao Sábio o livro que os fanáticos Escarlates guardam.",
			text = [=[Os {link:forsaken}Renegados{/link} têm uma história cheia de traição, diz o Sábio, e o pacto foi feito depressa demais. Talvez {link:cairne-bloodhoof}Cairne{/link} devesse ter dado ouvidos aos avisos de {link:orgrimmar}Orgrimmar{/link}. Os fanáticos da {link:scarlet-crusade}Cruzada Escarlate{/link} são loucos, mas estudaram os mortos-vivos, e Truthseeker queria saber o que haviam aprendido. Ele começara a se perguntar se o livro deles sequer existia.]=],
		},
		{
			title = "Os Discos de Platina",
			hint = "Traga ao Sábio uma relíquia das câmaras de Uldaman.",
			text = [=[De {link:uldaman}Uldaman{/link} veio uma cópia em miniatura dos discos de platina de Norgannon. O Sábio sentiu neles segredos que a terra guardara com força por eras. Pôs-se a aprender como funcionavam, e prometeu que se revelariam com o tempo.]=],
		},
		{
			title = "Presságios de Uldum",
			hint = "Siga os glifos traduzidos dos discos.",
			text = [=[Os glifos dos discos falavam de um lugar chamado {link:valley-of-the-watchers}Uldum{/link}, que a maioria acredita ser um mito. Truthseeker levou o assunto a {link:nara-wildmane}Nara Wildmane{/link}, que vira os portões selados no Vale dos Vigilantes, em {link:tanaris}Tanaris{/link}. Juntos, concluíram que os discos e Uldum estavam ligados.]=],
		},
	},
	mentions = {
		{ text = "Os Discos de Platina" },
		{ text = "Vendo o Que Acontece" },
		{ text = "Uma Tarefa Futura" },
	},
	bonds = {
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "a quem ele confiaria a própria vida" },
		{ id = "nara-wildmane", name = "Nara Wildmane", note = "partilha seu estudo de Uldum" },
		{ id = "magatha-grimtotem", name = "Magatha Grimtotem", note = "defensora do pacto de que ele desconfia" },
	},
})

