Translate("ptBR", "grimtotem-clan", {
	title = "Clã Temível Totem",
	aliases = { "clã Temível Totem", "tribo Temível Totem", "os Temível Totem" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Temível Totem são um clã {link:tauren}tauren{/link} diferente dos outros. Onde a maioria dos tauren busca harmonia com a terra, os Temível Totem buscam dominá-la. Acreditam que as raças inferiores devem ser expulsas de {link:kalimdor}Kalimdor{/link} e que os tauren devem retomar as terras de seus ancestrais. Sua matriarca é {link:magatha-grimtotem}Magatha{/link}, a Velha Anciã, e seus guerreiros a seguem.]=],
		},
		{
			title = "O Clã e a Cidade",
			text = [=[{link:magatha-grimtotem}Magatha{/link} vive no {link:elder-rise}Platô dos Anciãos{/link}, no {link:thunder-bluff}Penhasco do Trovão{/link}, guardada por guerreiros de seu clã, e os Temível Totem ali gozam dos direitos de qualquer {link:tauren}tauren{/link}. Diz-se que {link:cairne-bloodhoof}Cairne{/link} lhe deu um lugar tão perto de si no espírito de um velho ditado: mantenha seus amigos perto e seus inimigos mais perto ainda. Nas terras selvagens, o clã é outra história.]=],
		},
		{
			title = "Nas Terras Selvagens",
			text = [=[• {b}{link:thousand-needles}Mil Agulhas{/link}.{/b} Os Temível Totem dominam o {link:darkcloud-pinnacle}Pináculo da Nuvem Negra{/link}, onde enterram seus mortos junto a um fogo sagrado. Os {link:tauren}tauren{/link} da {link:freewind-post}Aldeia Vento Livre{/link} os vigiam de perto. Agentes de origem desconhecida foram vistos visitando-os, e um pária do clã, {link:arnak-grimtotem}Arnak{/link}, é procurado por assassinato e rapto.
• {b}A {link:stonetalon-mountains}Cordilheira das Torres de Pedra{/link}.{/b} Saqueadores Temível Totem caíram sobre uma aldeia tauren perto das montanhas e mataram quase todos que viviam nela.
• {b}A {link:earthen-ring}Harmonia Telúrica{/link}.{/b} Nem todo Temível Totem segue o caminho do clã. Nestes dias, um xamã chamado Yorn Grimtotem serve com a Harmonia Telúrica em {link:mulgore}Mulgore{/link}.]=],
		},
	},
})
